INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT141-S2-Q1$batch05$, 141, 2, 1, $batch05$Necessary Assumption$batch05$, $batch05$Editorial: The city has chosen a contractor to upgrade the heating systems in public buildings. Only 40 percent of the technicians employed by this contractor are certified by the Heating Technicians Association. So the city selected a contractor 60 percent of whose technicians are unqualified, which is an outrage.$batch05$, $batch05$Which one of the following is an assumption required by the argument in the editorial?$batch05$, $batch05$C$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=141 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$Certified technicians receive higher pay than uncertified technicians.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$There are no contractors with fewer than 40 percent of their technicians certified.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$Technicians who lack certification are not qualified technicians.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$Qualified technicians installed the heating systems to be upgraded.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$The contractor hired by the city has personal ties to city officials.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The city picked a contractor with 60 percent unqualified technicians.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Only 40 percent of the contractor's technicians are certified.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$"Not certified" goes in; "unqualified" comes out. Those are not the same word. A technician can be skilled and experienced without holding this one association's certificate. When an argument quietly swaps one term for another, the answer equates them.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: uncertified technicians are unqualified.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Pay has nothing to do with qualification.$batch05$), ($batch05$B$batch05$, $batch05$Other contractors being worse would not change whether this one's technicians are qualified.$batch05$), ($batch05$C$batch05$, $batch05$Negate it: "some technicians who lack certification *are* qualified." Then the 60 percent figure is not a count of unqualified people, and the outrage loses its basis.$batch05$), ($batch05$D$batch05$, $batch05$Who installed the old systems says nothing about the contractor's workers.$batch05$), ($batch05$E$batch05$, $batch05$Personal ties might be another reason to object, but the editorial's argument is about qualifications.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT141-S2-Q1$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
